#include "scene_gpu.h"

#include "photoreal_shaders.h"  // generated by build.py: kStreamTrianglesGs, kAlphaBakeCs (DXBC)
#include "core/dxbc.h"

#include <algorithm>
#include <cstdio>
#include <cstring>

namespace photoreal
{
    namespace
    {
        // The buffer a capture starts with: 2.8 M triangles at 48 bytes. B's direct draws alone needed about 67 MB.
        constexpr uint64_t kBufferStart = 128ull << 20;
        constexpr uint64_t kBufferStep = 16ull << 20;
        constexpr uint64_t kBufferMax = 512ull << 20;
        // The buffer begin_frame copies kUnwrittenBits from, again and again until the stream-output buffer is covered.
        constexpr uint32_t kMarkerBytes = 4u << 20;
        // A frame's alpha programs' constant rows: 4 MB, room for the whole 64 KB range of 64 dynamically indexed draws.
        constexpr uint32_t kConstantBytes = 4u << 20;
        constexpr uint32_t kAtlasTiles = 256;
        constexpr uint32_t kTileBytes = kAtlasTile * kAtlasTile;

        // D3D11_TEXTURE_ADDRESS_CLAMP for u and v, the default sampler's.
        constexpr uint32_t kClampAddress = 3 | 3 << 3;

        // DXGI_FORMAT_BC1_TYPELESS to BC5_SNORM and BC6H_TYPELESS to BC7_UNORM_SRGB: a texture of these is made of 4x4 blocks.
        bool block_compressed(DXGI_FORMAT f) { return (f >= 70 && f <= 84) || (f >= 94 && f <= 99); }

        template <class T>
        void release(T *&item)
        {
            if (item)
            {
                item->Release();
                item = nullptr;
            }
        }

        std::string hresult(const char *call, HRESULT hr)
        {
            char text[96];
            std::snprintf(text, sizeof text, "%s 0x%08X", call, static_cast<unsigned>(hr));
            return text;
        }

        // How a draw replays: a triangle list as a point list, whose corners in index order are its triangles; a patch list
        // as it is, through shaders/stream_triangles_gs.hlsl, which streams each of the tessellator's triangles as its
        // three corners; anything else not at all. A strip's points would need its restarts and winding rebuilt, and the
        // census has none.
        enum class Replay { points, triangles, none };
        Replay replay_of(D3D11_PRIMITIVE_TOPOLOGY topology, bool domain)
        {
            if (domain)
                return topology >= D3D11_PRIMITIVE_TOPOLOGY_1_CONTROL_POINT_PATCHLIST && topology <= D3D11_PRIMITIVE_TOPOLOGY_32_CONTROL_POINT_PATCHLIST
                    ? Replay::triangles : Replay::none;
            return topology == D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST ? Replay::points : Replay::none;
        }

        // The pixel shader's inputs t0 to t7, as NativeDraw reads them.
        void read_inputs(ID3D11DeviceContext *context, std::array<Texture, 8> &out)
        {
            ID3D11ShaderResourceView *srvs[8] = {};
            context->PSGetShaderResources(0, 8, srvs);
            for (size_t slot = 0; slot < 8; slot++)
            {
                if (srvs[slot] == nullptr)
                    continue;
                ComPtr<ID3D11Resource> resource;
                srvs[slot]->GetResource(resource.GetAddressOf());
                out[slot].id = static_cast<ResourceId>(reinterpret_cast<uintptr_t>(resource.Get()));
                ComPtr<ID3D11Texture2D> texture;
                if (SUCCEEDED(resource.As(&texture)))
                {
                    D3D11_TEXTURE2D_DESC desc;
                    texture->GetDesc(&desc);
                    out[slot].format = static_cast<Format>(desc.Format);
                    out[slot].size = { desc.Width, desc.Height };
                }
                srvs[slot]->Release();
            }
        }

        template <class Shader>
        uint64_t handle_of(const ComPtr<Shader> &shader) { return reinterpret_cast<uintptr_t>(shader.Get()); }
    }

    ReplayGuard::ReplayGuard(ID3D11DeviceContext *context, const char *&moved) : context_(context), moved_(moved)
    {
        context_->OMGetRenderTargets(1, &rtv_, &dsv_);
        context_->PSGetShader(&ps_, nullptr, nullptr);
        context_->GSGetShader(&gs_, gs_instances_, &gs_count_);
        context_->OMGetBlendState(&blend_, blend_factor_, &sample_mask_);
        context_->OMGetDepthStencilState(&depth_stencil_, &stencil_ref_);
        context_->IAGetPrimitiveTopology(&topology_);
        context_->SOGetTargets(kSoSlots, so_);
    }

    ReplayGuard::~ReplayGuard()
    {
        context_->GSSetShader(gs_, gs_instances_, gs_count_);
        context_->OMSetBlendState(blend_, blend_factor_, sample_mask_);
        context_->OMSetDepthStencilState(depth_stencil_, stencil_ref_);
        context_->IASetPrimitiveTopology(topology_);
        if (!game_so())
        {
            ID3D11Buffer *const none[kSoSlots] = {};
            context_->SOSetTargets(kSoSlots, none, nullptr);
        }

        ID3D11RenderTargetView *rtv = nullptr;
        ID3D11DepthStencilView *dsv = nullptr;
        ID3D11PixelShader *ps = nullptr;
        ID3D11GeometryShader *gs = nullptr;
        ID3D11BlendState *blend = nullptr;
        FLOAT factor[4];
        UINT mask = 0, ref = 0;
        ID3D11DepthStencilState *depth_stencil = nullptr;
        ID3D11Buffer *so = nullptr;
        D3D11_PRIMITIVE_TOPOLOGY topology = D3D11_PRIMITIVE_TOPOLOGY_UNDEFINED;
        context_->IAGetPrimitiveTopology(&topology);
        context_->OMGetRenderTargets(1, &rtv, &dsv);
        context_->PSGetShader(&ps, nullptr, nullptr);
        context_->GSGetShader(&gs, nullptr, nullptr);
        context_->OMGetBlendState(&blend, factor, &mask);
        context_->OMGetDepthStencilState(&depth_stencil, &ref);
        context_->SOGetTargets(1, &so);
        if (rtv != rtv_)
            moved_ = "render target 0";
        else if (dsv != dsv_)
            moved_ = "depth-stencil view";
        else if (ps != ps_)
            moved_ = "pixel shader";
        else if (gs != gs_)
            moved_ = "geometry shader";
        else if (blend != blend_ || mask != sample_mask_)
            moved_ = "blend state";
        else if (depth_stencil != depth_stencil_ || ref != stencil_ref_)
            moved_ = "depth-stencil state";
        else if (topology != topology_)
            moved_ = "primitive topology";
        else if (so != so_[0])
            moved_ = "stream-output target";
        for (IUnknown *item : std::initializer_list<IUnknown *> { rtv, dsv, ps, gs, blend, depth_stencil, so, rtv_, dsv_, ps_, gs_, blend_, depth_stencil_ })
            if (item)
                item->Release();
        for (ID3D11Buffer *&target : so_)
            release(target);
        for (ID3D11ClassInstance *&instance : gs_instances_)
            release(instance);
    }

    void SceneGpu::init(ID3D11Device *device, ID3D11DeviceContext1 *context, ID3D11BlendState *no_write, ID3D11DepthStencilState *no_depth)
    {
        *this = SceneGpu {};
        device_ = device;
        context_ = context;
        no_write_ = no_write;
        no_depth_ = no_depth;
    }

    bool SceneGpu::make_buffers(uint64_t bytes)
    {
        D3D11_BUFFER_DESC so = {};
        so.ByteWidth = static_cast<UINT>(bytes);
        so.Usage = D3D11_USAGE_DEFAULT;
        so.BindFlags = D3D11_BIND_STREAM_OUTPUT;
        D3D11_BUFFER_DESC staging = {};
        staging.ByteWidth = static_cast<UINT>(bytes);
        staging.Usage = D3D11_USAGE_STAGING;
        staging.CPUAccessFlags = D3D11_CPU_ACCESS_READ;
        ComPtr<ID3D11Buffer> buffer, readable;
        if (FAILED(device_->CreateBuffer(&so, nullptr, buffer.GetAddressOf())) || FAILED(device_->CreateBuffer(&staging, nullptr, readable.GetAddressOf())))
            return false;
        so_buffer_ = buffer;
        so_staging_ = readable;
        buffer_bytes_ = bytes;
        return true;
    }

    std::optional<std::string> SceneGpu::begin()
    {
        end();
        if (!make_buffers(kBufferStart))
            return "the 128 MB stream-output buffer could not be made";
        D3D11_BUFFER_DESC desc = {};
        desc.ByteWidth = kMarkerBytes;
        desc.Usage = D3D11_USAGE_DEFAULT;
        desc.BindFlags = 0;
        std::vector<uint32_t> marker(kMarkerBytes / sizeof(uint32_t), kUnwrittenBits);
        const D3D11_SUBRESOURCE_DATA data = { marker.data(), 0, 0 };
        if (FAILED(device_->CreateBuffer(&desc, &data, marker_.GetAddressOf())))
        {
            end();
            return "the stream-output buffer's clear source could not be made";
        }
        return std::nullopt;
    }

    void SceneGpu::end()
    {
        atlas_.Reset();
        atlas_staging_.Reset();
        atlas_uav_.Reset();
        constants_staging_.Reset();
        alpha_failed_ = false;
        tiles_.clear();
        bakes_.clear();
        constants_used_ = copied_constants_ = 0;
        copied_tiles_ = 0;
        so_buffer_.Reset();
        so_staging_.Reset();
        marker_.Reset();
        buffer_bytes_ = 0;
        hints_.clear();
        queries_.clear();
        records_.clear();
        replays_ = 0;
        layout_ = {};
        copied_.clear();
        copied_replays_ = 0;
        copied_frame_ = false;
        depth_ = Mirror {};
        depth_staging_.Reset();
        depth_size_ = {};
        picture_ = Staging {};
        picture_copied_ = false;
        normals_ = mask_ = irradiance_ = stencil_ = albedo_ = hdr_ = Mirror {};
        gbuffer_copied_ = gbuffer_back_ = hdr_copied_ = hdr_back_copied_ = false;
        normals_back_.reset();
        mask_back_.reset();
        irradiance_back_.reset();
        stencil_back_.reset();
        albedo_back_.reset();
        hdr_back_.reset();
    }

    void SceneGpu::begin_frame()
    {
        gbuffer_copied_ = hdr_copied_ = false;
        records_.clear();
        replays_ = 0;
        // The constants start again with the frame's draws; the atlas's tiles, and the textures waiting for their bake,
        // stay for the whole capture.
        constants_used_ = 0;
        layout_ = {};
        layout_.capacity = buffer_bytes_ / kCornerBytes;
        if (!so_buffer_ || !marker_)
            return;
        for (uint64_t at = 0; at < buffer_bytes_; at += kMarkerBytes)
        {
            const D3D11_BOX box = { 0, 0, 0, static_cast<UINT>(std::min<uint64_t>(kMarkerBytes, buffer_bytes_ - at)), 1, 1 };
            context_->CopySubresourceRegion(so_buffer_.Get(), 0, static_cast<UINT>(at), 0, 0, marker_.Get(), 0, &box);
        }
    }

    bool SceneGpu::same_entries(const std::vector<SoEntry> &a, const std::vector<SoEntry> &b)
    {
        return a.size() == b.size() && std::equal(a.begin(), a.end(), b.begin(), [](const SoEntry &x, const SoEntry &y) {
            return x.semantic == y.semantic && x.index == y.index && x.start == y.start && x.count == y.count && x.slot == y.slot;
        });
    }

    const SceneGpu::CachedGs &SceneGpu::geometry_shader(uint64_t key, const std::string &bytes, const std::vector<SoEntry> &extra)
    {
        // The key of a declaration with extra entries mixes them in, so each set of inputs has its own shader.
        for (const SoEntry &e : extra)
            for (const uint64_t v : { shader_hash(e.semantic.data(), e.semantic.size()), uint64_t(e.index) << 16 | uint64_t(e.start) << 8 | e.count })
                key = (key ^ v) * 0x100000001b3ull;
        const auto [it, made] = gs_cache_.try_emplace(key);
        CachedGs &cached = it->second;
        if (!made)
            return cached;
        const std::optional<OutputSignature> signature = parse_output_signature(reinterpret_cast<const uint8_t *>(bytes.data()), bytes.size());
        std::string missing;
        const std::optional<SoDeclaration> declaration = signature ? so_declaration(*signature, extra, missing) : std::nullopt;
        if (!declaration)
        {
            cached.skip = DrawSkip::no_position;
            return cached;
        }
        std::vector<D3D11_SO_DECLARATION_ENTRY> entries;
        for (const SoEntry &e : declaration->entries)
            entries.push_back({ 0, e.semantic.c_str(), e.index, e.start, e.count, e.slot });
        const UINT stride = declaration->stride;
        cached.result = device_->CreateGeometryShaderWithStreamOutput(bytes.data(), bytes.size(), entries.data(), static_cast<UINT>(entries.size()), &stride,
            1, D3D11_SO_NO_RASTERIZED_STREAM, nullptr, cached.shader.GetAddressOf());
        if (FAILED(cached.result))
        {
            cached.shader.Reset();
            cached.skip = DrawSkip::gs_create_failed;
        }
        return cached;
    }

    bool SceneGpu::make_alpha()
    {
        if (atlas_ && constants_staging_ && bake_cs_)
            return true;
        if (alpha_failed_)
            return false;
        D3D11_BUFFER_DESC atlas = {};
        atlas.ByteWidth = kAtlasTiles * kTileBytes;
        atlas.Usage = D3D11_USAGE_DEFAULT;
        atlas.BindFlags = D3D11_BIND_UNORDERED_ACCESS;
        atlas.MiscFlags = D3D11_RESOURCE_MISC_BUFFER_ALLOW_RAW_VIEWS;
        D3D11_BUFFER_DESC readable = {};
        readable.ByteWidth = atlas.ByteWidth;
        readable.Usage = D3D11_USAGE_STAGING;
        readable.CPUAccessFlags = D3D11_CPU_ACCESS_READ;
        D3D11_BUFFER_DESC constants = readable;
        constants.ByteWidth = kConstantBytes;
        D3D11_BUFFER_DESC bake = {};
        bake.ByteWidth = 16;
        bake.Usage = D3D11_USAGE_DYNAMIC;
        bake.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
        bake.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
        D3D11_UNORDERED_ACCESS_VIEW_DESC view = {};
        view.Format = DXGI_FORMAT_R32_TYPELESS;
        view.ViewDimension = D3D11_UAV_DIMENSION_BUFFER;
        view.Buffer.NumElements = atlas.ByteWidth / 4;
        view.Buffer.Flags = D3D11_BUFFER_UAV_FLAG_RAW;
        D3D11_SAMPLER_DESC sampler = {};
        sampler.Filter = D3D11_FILTER_MIN_MAG_MIP_LINEAR;
        sampler.AddressU = sampler.AddressV = sampler.AddressW = D3D11_TEXTURE_ADDRESS_CLAMP;
        sampler.MaxLOD = D3D11_FLOAT32_MAX;
        if (FAILED(device_->CreateBuffer(&atlas, nullptr, atlas_.ReleaseAndGetAddressOf()))
            || FAILED(device_->CreateUnorderedAccessView(atlas_.Get(), &view, atlas_uav_.ReleaseAndGetAddressOf()))
            || FAILED(device_->CreateBuffer(&readable, nullptr, atlas_staging_.ReleaseAndGetAddressOf()))
            || FAILED(device_->CreateBuffer(&constants, nullptr, constants_staging_.ReleaseAndGetAddressOf()))
            || FAILED(device_->CreateBuffer(&bake, nullptr, bake_constants_.ReleaseAndGetAddressOf()))
            || FAILED(device_->CreateComputeShader(kAlphaBakeCs, sizeof kAlphaBakeCs, nullptr, bake_cs_.ReleaseAndGetAddressOf()))
            || FAILED(device_->CreateSamplerState(&sampler, bake_sampler_.ReleaseAndGetAddressOf())))
        {
            atlas_.Reset();
            atlas_uav_.Reset();
            atlas_staging_.Reset();
            constants_staging_.Reset();
            bake_cs_.Reset();
            alpha_failed_ = true;
            return false;
        }
        return true;
    }

    bool SceneGpu::copy_constants(const AlphaProgram &program, SceneDrawRecord &r)
    {
        ID3D11DeviceContext1 *c = context_.Get();
        struct Copy
        {
            ComPtr<ID3D11Buffer> buffer;
            UINT first = 0, count = 0;
        };
        std::vector<Copy> copies;
        uint64_t rows = 0;
        for (const CbRows &range : program.rows)
        {
            Copy copy;
            UINT first = 0, bound = 0;
            c->PSGetConstantBuffers1(range.slot, 1, copy.buffer.GetAddressOf(), &first, &bound);
            if (!copy.buffer)
                return false;
            D3D11_BUFFER_DESC desc;
            copy.buffer->GetDesc(&desc);
            // The bound range as the census measures it: its count, or the whole buffer when bound without one.
            const UINT offset = first * 16;
            const UINT available = offset < desc.ByteWidth ? std::min(bound != 0 ? bound * 16 : desc.ByteWidth, desc.ByteWidth - offset) / 16 : 0;
            copy.first = first + range.first;
            copy.count = range.dynamic ? std::min<UINT>(available, kAlphaDynamicRows) : range.count;
            if (copy.count == 0 || range.first + copy.count > available)
                return false;
            rows += copy.count;
            copies.push_back(copy);
        }
        if (constants_used_ + rows * 16 > kConstantBytes)
            return false;
        r.alpha_constants = constants_used_ / 4;
        r.alpha_rows = static_cast<uint32_t>(rows);
        for (const Copy &copy : copies)
        {
            const D3D11_BOX box = { copy.first * 16, 0, 0, (copy.first + copy.count) * 16, 1, 1 };
            c->CopySubresourceRegion(constants_staging_.Get(), 0, static_cast<UINT>(constants_used_), 0, 0, copy.buffer.Get(), 0, &box);
            constants_used_ += uint64_t(copy.count) * 16;
        }
        return true;
    }

    DrawAlpha SceneGpu::copy_texture(const AlphaProgram &program, SceneDrawRecord &r)
    {
        ID3D11DeviceContext1 *c = context_.Get();
        r.alpha_address = kClampAddress;
        if (program.sampler != kNoSlot)
        {
            ComPtr<ID3D11SamplerState> sampler;
            c->PSGetSamplers(program.sampler, 1, sampler.GetAddressOf());
            if (sampler)
            {
                D3D11_SAMPLER_DESC desc;
                sampler->GetDesc(&desc);
                r.alpha_address = static_cast<uint32_t>(desc.AddressU) | static_cast<uint32_t>(desc.AddressV) << 3;
            }
        }
        if (program.texture == kNoSlot)
            return DrawAlpha::program;
        ComPtr<ID3D11ShaderResourceView> srv;
        c->PSGetShaderResources(program.texture, 1, srv.GetAddressOf());
        if (!srv)
            return DrawAlpha::texture;
        D3D11_SHADER_RESOURCE_VIEW_DESC view;
        srv->GetDesc(&view);
        ComPtr<ID3D11Resource> resource;
        srv->GetResource(resource.GetAddressOf());
        ComPtr<ID3D11Texture2D> texture;
        if (view.ViewDimension != D3D11_SRV_DIMENSION_TEXTURE2D || FAILED(resource.As(&texture)))
            return DrawAlpha::texture;
        D3D11_TEXTURE2D_DESC desc;
        texture->GetDesc(&desc);
        r.alpha_texture = { static_cast<ResourceId>(reinterpret_cast<uintptr_t>(resource.Get())), static_cast<Format>(view.Format), { desc.Width, desc.Height } };
        const auto key = std::make_tuple(reinterpret_cast<uintptr_t>(resource.Get()), static_cast<uint32_t>(view.Format), uint32_t(program.channel));
        if (const auto known = tiles_.find(key); known != tiles_.end())
        {
            r.alpha_tile = known->second;
            return DrawAlpha::program;
        }
        if (tiles_.size() >= kAtlasTiles)
            return DrawAlpha::atlas_full;
        // The first mip of the view whose larger side is at most 256, or its smallest.
        const UINT first = view.Texture2D.MostDetailedMip;
        const UINT mips = std::min<UINT>(view.Texture2D.MipLevels, desc.MipLevels - std::min(first, desc.MipLevels));
        if (mips == 0)
            return DrawAlpha::texture;
        UINT mip = first;
        while (mip + 1 < first + mips && std::max(desc.Width >> mip, desc.Height >> mip) > kAtlasTile)
            mip++;
        const UINT width = std::max(desc.Width >> mip, 1u), height = std::max(desc.Height >> mip, 1u);
        // A block-compressed texture of ours must be whole blocks.
        if (block_compressed(desc.Format) && (width % 4 != 0 || height % 4 != 0))
            return DrawAlpha::texture;
        D3D11_TEXTURE2D_DESC copy = {};
        copy.Width = width;
        copy.Height = height;
        copy.MipLevels = copy.ArraySize = 1;
        copy.Format = desc.Format;
        copy.SampleDesc.Count = 1;
        copy.Usage = D3D11_USAGE_DEFAULT;
        copy.BindFlags = D3D11_BIND_SHADER_RESOURCE;
        D3D11_SHADER_RESOURCE_VIEW_DESC copy_view = {};
        copy_view.Format = view.Format;
        copy_view.ViewDimension = D3D11_SRV_DIMENSION_TEXTURE2D;
        copy_view.Texture2D.MipLevels = 1;
        ComPtr<ID3D11Texture2D> ours;
        Bake pending;
        if (FAILED(device_->CreateTexture2D(&copy, nullptr, ours.GetAddressOf()))
            || FAILED(device_->CreateShaderResourceView(ours.Get(), &copy_view, pending.source.GetAddressOf())))
            return DrawAlpha::texture;
        c->CopySubresourceRegion(ours.Get(), 0, 0, 0, 0, texture.Get(), D3D11CalcSubresource(mip, 0, desc.MipLevels), nullptr);
        pending.tile = static_cast<uint32_t>(tiles_.size());
        pending.channel = program.channel;
        tiles_.emplace(key, pending.tile);
        bakes_.push_back(pending);
        r.alpha_tile = pending.tile;
        return DrawAlpha::program;
    }

    void SceneGpu::prepare_alpha(SceneDrawRecord &r, const std::optional<ShaderCode> &ps, const std::optional<ShaderCode> &source, bool tessellated,
        std::vector<SoEntry> &extra)
    {
        extra.clear();
        r.stride = kCornerBytes;
        const DrawClass cls = draw_class(r);
        if (cls == DrawClass::s133 || cls == DrawClass::s165 || cls == DrawClass::s129)
        {
            r.alpha = DrawAlpha::character;
            return;
        }
        if (!ps)
        {
            r.alpha = DrawAlpha::none;
            return;
        }
        if (!ps->code)
        {
            r.alpha = DrawAlpha::no_bytecode;
            return;
        }
        std::shared_ptr<const AlphaAnalysis> &analysis = analyses_[ps->hash];
        if (!analysis)
            analysis = std::make_shared<const AlphaAnalysis>(analyze_alpha(reinterpret_cast<const uint8_t *>(ps->code->data()), ps->code->size()));
        r.analysis = analysis;
        if (!analysis->program)
        {
            // No program without a reason: no discard at all, or dither alone.
            r.alpha = !analysis->why.empty() ? DrawAlpha::unsupported : analysis->discards.empty() ? DrawAlpha::none : DrawAlpha::dither;
            return;
        }
        const AlphaProgram &program = *analysis->program;
        if (tessellated)
        {
            r.alpha = DrawAlpha::tessellated;
            return;
        }
        // DXVK skips an entry the vertex shader does not write, which would leave garbage in its place.
        const std::optional<OutputSignature> signature = parse_output_signature(reinterpret_cast<const uint8_t *>(source->code->data()), source->code->size());
        std::string missing;
        if (!signature || !so_declaration(*signature, program.so_entries(), missing))
        {
            r.alpha = DrawAlpha::outputs;
            return;
        }
        if (!make_alpha() || !copy_constants(program, r))
        {
            r.alpha = DrawAlpha::constants;
            return;
        }
        r.alpha = copy_texture(program, r);
        if (r.alpha != DrawAlpha::program)
            return;
        extra = program.so_entries();
        r.stride = kCornerBytes + 4 * program.attribute_floats();
    }

    std::optional<std::string> SceneGpu::replay(const ReplayCall &call, const ShaderRegistry &shaders, const char *&moved)
    {
        if (!so_buffer_)
            return std::nullopt;
        ID3D11DeviceContext1 *c = context_.Get();
        SceneDrawRecord &r = records_.emplace_back();
        r.index = static_cast<uint32_t>(records_.size() - 1);
        r.kind = call.kind;
        r.count = call.count;
        r.instances = call.instances;
        r.first = call.first;
        r.base_vertex = call.base_vertex;
        r.first_instance = call.first_instance;
        r.args_offset = call.args_offset;

        ComPtr<ID3D11VertexShader> vs;
        ComPtr<ID3D11DomainShader> ds;
        ComPtr<ID3D11GeometryShader> gs;
        ComPtr<ID3D11PixelShader> ps;
        c->VSGetShader(vs.GetAddressOf(), nullptr, nullptr);
        c->DSGetShader(ds.GetAddressOf(), nullptr, nullptr);
        c->GSGetShader(gs.GetAddressOf(), nullptr, nullptr);
        c->PSGetShader(ps.GetAddressOf(), nullptr, nullptr);
        D3D11_PRIMITIVE_TOPOLOGY topology = D3D11_PRIMITIVE_TOPOLOGY_UNDEFINED;
        c->IAGetPrimitiveTopology(&topology);
        r.topology = static_cast<uint32_t>(topology);
        ComPtr<ID3D11DepthStencilState> depth_state;
        UINT stencil_ref = 0;
        c->OMGetDepthStencilState(depth_state.GetAddressOf(), &stencil_ref);
        // A null state is D3D11's default: depth test LESS with writes, stencil off.
        D3D11_DEPTH_STENCIL_DESC depth = {};
        depth.DepthEnable = TRUE;
        depth.DepthWriteMask = D3D11_DEPTH_WRITE_MASK_ALL;
        depth.DepthFunc = D3D11_COMPARISON_LESS;
        if (depth_state)
            depth_state->GetDesc(&depth);
        r.stencil = depth.StencilEnable != FALSE;
        r.stencil_ref = stencil_ref;
        r.depth_func = depth.DepthEnable ? static_cast<uint32_t>(depth.DepthFunc) : 0;
        r.depth_write = depth.DepthEnable && depth.DepthWriteMask == D3D11_DEPTH_WRITE_MASK_ALL;
        read_inputs(c, r.ps_inputs);

        const std::optional<ShaderCode> vs_code = vs ? shaders.find(handle_of(vs)) : std::nullopt;
        const std::optional<ShaderCode> ds_code = ds ? shaders.find(handle_of(ds)) : std::nullopt;
        const std::optional<ShaderCode> ps_code = ps ? shaders.find(handle_of(ps)) : std::nullopt;
        r.vs = vs_code ? vs_code->hash : 0;
        r.ds = ds_code ? ds_code->hash : 0;
        r.ps = ps_code ? ps_code->hash : 0;
        // The stage before the rasterizer writes the position: the domain shader when the draw is tessellated.
        const std::optional<ShaderCode> &source = ds ? ds_code : vs_code;
        const Replay mode = replay_of(topology, ds != nullptr);
        r.points = mode == Replay::points;
        if (gs)
            r.skip = DrawSkip::gs_bound;
        else if (!source || !source->code)
            r.skip = DrawSkip::no_bytecode;
        else if (mode == Replay::none)
            r.skip = DrawSkip::topology;
        else if (replays_ >= kSceneQueries)
            r.skip = DrawSkip::query_pool;
        if (r.skip != DrawSkip::none)
            return std::nullopt;

        // A tessellated draw streams through our own geometry shader, which takes the tessellator's triangles: its domain
        // must be tri or quad, as every hull shader of the census's makes triangles of it.
        if (ds)
        {
            const std::optional<TessellatorDomain> domain = tessellator_domain(reinterpret_cast<const uint8_t *>(source->code->data()), source->code->size());
            if (!domain || *domain == TessellatorDomain::isoline)
            {
                r.skip = DrawSkip::topology;
                return std::nullopt;
            }
        }
        std::vector<SoEntry> extra;
        prepare_alpha(r, ps_code, source, ds != nullptr, extra);
        // The key of our own shader: a census hash is FNV-1a of bytecode, never 0.
        static const std::string triangles_gs(reinterpret_cast<const char *>(kStreamTrianglesGs), sizeof kStreamTrianglesGs);
        // One stream layout per source shader, the first a capture made for it: build 207's equal-depth vegetation draws
        // asked for the position alone after their prepass draws had streamed the same vertex shader with an alpha
        // program's inputs, and their data came back in the prepass's layout, read as garbage. A later draw therefore
        // streams with the first layout and is read with it; one whose own program wants other inputs casts whole.
        const auto first = ds ? layouts_.end() : layouts_.find(source->hash);
        if (first != layouts_.end() && !same_entries(first->second.extra, extra))
        {
            if (!extra.empty())
                r.alpha = DrawAlpha::stream;
            extra = first->second.extra;
            r.stride = first->second.stride;
        }
        const CachedGs *found = ds ? &geometry_shader(0, triangles_gs, {}) : &geometry_shader(source->hash, *source->code, extra);
        if (!extra.empty() && found->skip != DrawSkip::none && first == layouts_.end())
        {
            // Without its alpha program's inputs, the draw still streams its triangles, whole.
            r.alpha = DrawAlpha::stream;
            r.stride = kCornerBytes;
            extra.clear();
            found = &geometry_shader(source->hash, *source->code, {});
        }
        if (!ds && found->skip == DrawSkip::none)
            layouts_.try_emplace(source->hash, StreamLayoutOf { extra, r.stride });
        const CachedGs &so_gs = *found;
        if (so_gs.result == DXGI_ERROR_INVALID_CALL && !ds)
        {
            // DXVK refuses every stream-output shader this way when the Vulkan driver lacks transform feedback. Our own
            // shader for tessellated draws failing only leaves those draws out, as gs-create-failed.
            support_ = 2;
            r.skip = DrawSkip::gs_create_failed;
            return "stream output unsupported (" + hresult("CreateGeometryShaderWithStreamOutput", so_gs.result) + ")";
        }
        if (so_gs.skip != DrawSkip::none)
        {
            r.skip = so_gs.skip;
            return std::nullopt;
        }
        if (queries_.size() <= replays_)
        {
            const D3D11_QUERY_DESC desc = { D3D11_QUERY_SO_STATISTICS, 0 };
            ComPtr<ID3D11Query> query;
            const HRESULT hr = device_->CreateQuery(&desc, query.GetAddressOf());
            if (FAILED(hr))
            {
                r.skip = DrawSkip::query_pool;
                return "the stream-output statistics query could not be made (" + hresult("CreateQuery", hr) + ")";
            }
            queries_.push_back(query);
        }
        if (!place_draw(layout_, r, hints_))
            return std::nullopt;

        std::optional<std::string> stop;
        {
            ReplayGuard guard(c, moved);
            if (guard.game_so())
                r.skip = DrawSkip::game_so;
            else
            {
                ID3D11Buffer *const target = so_buffer_.Get();
                // Its own place, never an append: what a draw wrote is then read from where it wrote it, whatever the one
                // before it did.
                const UINT offset = static_cast<UINT>(r.offset * kCornerBytes);
                c->GSSetShader(so_gs.shader.Get(), nullptr, 0);
                c->SOSetTargets(1, &target, &offset);
                if (r.points)
                    c->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_POINTLIST);
                c->OMSetBlendState(no_write_.Get(), nullptr, 0xFFFFFFFF);
                c->OMSetDepthStencilState(no_depth_.Get(), 0);
                // The set calls return nothing, so the bindings are read back before anything draws through them.
                ComPtr<ID3D11Buffer> bound;
                ComPtr<ID3D11GeometryShader> bound_gs;
                c->SOGetTargets(1, bound.GetAddressOf());
                c->GSGetShader(bound_gs.GetAddressOf(), nullptr, nullptr);
                if (bound.Get() != target || bound_gs.Get() != so_gs.shader.Get())
                {
                    r.skip = DrawSkip::gs_create_failed;
                    stop = "the stream-output target or geometry shader did not bind";
                }
                else
                {
                    ID3D11Query *const query = queries_[replays_].Get();
                    c->Begin(query);
                    switch (call.kind)
                    {
                    case ReplayKind::draw:
                        c->DrawInstanced(call.count, call.instances, call.first, call.first_instance);
                        break;
                    case ReplayKind::indexed:
                        c->DrawIndexedInstanced(call.count, call.instances, call.first, call.base_vertex, call.first_instance);
                        break;
                    case ReplayKind::indirect:
                        c->DrawInstancedIndirect(call.args, call.args_offset);
                        break;
                    case ReplayKind::indirect_indexed:
                        c->DrawIndexedInstancedIndirect(call.args, call.args_offset);
                        break;
                    case ReplayKind::count:
                        break;
                    }
                    c->End(query);
                    r.query = replays_++;
                }
            }
        }
        return stop;
    }

    void SceneGpu::copy_gbuffer(const FrameMap &map, GbufferCopies wanted)
    {
        // The main depth too, for its stencil plane, which later passes of the frame write over: copied at present, the
        // view face's stencil held only 0 and 1 in builds 203 to 208, while the trace's save, copied here, held the
        // G-buffer's classes.
        const std::tuple<Entry, Mirror *, bool> copies[] = { { Entry::normals, &normals_, wanted.normals_irradiance }, { Entry::shadow_mask, &mask_, wanted.mask },
            { Entry::ambient_diffuse, &irradiance_, wanted.normals_irradiance }, { Entry::depth, &stencil_, true }, { Entry::albedo, &albedo_, wanted.albedo } };
        for (const auto &[entry, mirror, want] : copies)
        {
            const std::optional<Texture> &texture = map[entry];
            ID3D11Resource *game = want && texture ? reinterpret_cast<ID3D11Resource *>(static_cast<uint64_t>(texture->id)) : nullptr;
            if (game && mirror->sync(device_.Get(), game, static_cast<DXGI_FORMAT>(texture->format), false))
                mirror->copy_from(context_.Get(), game);
            else
                *mirror = Mirror {};
        }
        gbuffer_copied_ = true;
    }

    void SceneGpu::copy_hdr(const FrameMap &map)
    {
        const std::optional<Texture> &texture = map[Entry::hdr_scene];
        ID3D11Resource *game = texture ? reinterpret_cast<ID3D11Resource *>(static_cast<uint64_t>(texture->id)) : nullptr;
        hdr_copied_ = game && hdr_.sync(device_.Get(), game, static_cast<DXGI_FORMAT>(texture->format), false);
        if (hdr_copied_)
            hdr_.copy_from(context_.Get(), game);
    }

    void SceneGpu::bake(const char *&moved)
    {
        if (bakes_.empty() || !atlas_)
            return;
        ID3D11DeviceContext1 *c = context_.Get();
        StateGuard guard(c, moved);
        ID3D11UnorderedAccessView *const uavs[] = { atlas_uav_.Get() };
        ID3D11SamplerState *const samplers[] = { bake_sampler_.Get() };
        ID3D11Buffer *const buffers[] = { bake_constants_.Get() };
        c->CSSetShader(bake_cs_.Get(), nullptr, 0);
        c->CSSetUnorderedAccessViews(0, 1, uavs, nullptr);
        c->CSSetSamplers(0, 1, samplers);
        for (const Bake &b : bakes_)
        {
            D3D11_MAPPED_SUBRESOURCE mapped;
            if (FAILED(c->Map(bake_constants_.Get(), 0, D3D11_MAP_WRITE_DISCARD, 0, &mapped)))
                continue;
            const uint32_t values[4] = { b.tile, b.channel, 0, 0 };
            std::memcpy(mapped.pData, values, sizeof values);
            c->Unmap(bake_constants_.Get(), 0);
            ID3D11ShaderResourceView *const srvs[] = { b.source.Get() };
            c->CSSetConstantBuffers(0, 1, buffers);
            c->CSSetShaderResources(0, 1, srvs);
            c->Dispatch(kAtlasTile / 32, kAtlasTile / 8, 1);
        }
        bakes_.clear();
    }

    bool SceneGpu::copy_at_present(const std::optional<Texture> &depth, ID3D11Resource *back_buffer, const char *&moved)
    {
        if (!so_buffer_)
            return false;
        ID3D11DeviceContext1 *c = context_.Get();
        bake(moved);
        if (atlas_ && !tiles_.empty())
            c->CopyResource(atlas_staging_.Get(), atlas_.Get());
        copied_tiles_ = atlas_ ? static_cast<uint32_t>(tiles_.size()) : 0;
        copied_constants_ = constants_used_;
        constants_used_ = 0;
        copied_ = std::move(records_);
        copied_replays_ = replays_;
        copied_wanted_ = layout_.wanted;
        records_.clear();
        replays_ = 0;
        layout_ = {};
        c->CopyResource(so_staging_.Get(), so_buffer_.Get());

        depth_size_ = {};
        if (depth)
        {
            ID3D11Resource *game = reinterpret_cast<ID3D11Resource *>(static_cast<uint64_t>(depth->id));
            if (!depth_.sync(device_.Get(), game, static_cast<DXGI_FORMAT>(depth->format), false))
                return false;
            D3D11_TEXTURE2D_DESC desc = {};
            if (depth_staging_)
                depth_staging_->GetDesc(&desc);
            if (!depth_staging_ || desc.Width != depth->size.width || desc.Height != depth->size.height)
            {
                desc = {};
                desc.Width = depth->size.width;
                desc.Height = depth->size.height;
                desc.MipLevels = desc.ArraySize = 1;
                desc.Format = DXGI_FORMAT_R32G8X24_TYPELESS;
                desc.SampleDesc.Count = 1;
                desc.Usage = D3D11_USAGE_STAGING;
                desc.CPUAccessFlags = D3D11_CPU_ACCESS_READ;
                depth_staging_.Reset();
                if (FAILED(device_->CreateTexture2D(&desc, nullptr, depth_staging_.GetAddressOf())))
                    return false;
            }
            // The game's depth is a depth-stencil resource, so it reaches the CPU-readable texture through our mirror,
            // as copy_depth_texel's texel does.
            depth_.copy_from(c, game);
            depth_.copy_to(c, depth_staging_.Get());
            depth_size_ = depth->size;
        }
        picture_copied_ = back_buffer != nullptr && picture_.copy_from(device_.Get(), c, back_buffer);
        gbuffer_back_ = gbuffer_copied_;
        if (gbuffer_copied_)
        {
            // A mirror that was not made gives no copy, and read() leaves that file out.
            for (const auto &[mirror, back] : { std::pair { &normals_, &normals_back_ }, std::pair { &mask_, &mask_back_ }, std::pair { &irradiance_, &irradiance_back_ },
                     std::pair { &stencil_, &stencil_back_ }, std::pair { &albedo_, &albedo_back_ } })
                if (!mirror->texture() || !back->copy_from(device_.Get(), c, mirror->texture()))
                    back->reset();
        }
        hdr_back_copied_ = hdr_copied_ && hdr_back_.copy_from(device_.Get(), c, hdr_.texture());
        gbuffer_copied_ = hdr_copied_ = false;
        copied_frame_ = true;
        return true;
    }

    SceneRead SceneGpu::read()
    {
        SceneRead out;
        if (!copied_frame_ || !so_staging_)
        {
            out.state = SceneRead::State::failed;
            out.why = "no frame was copied";
            return out;
        }
        ID3D11DeviceContext1 *c = context_.Get();
        std::vector<D3D11_QUERY_DATA_SO_STATISTICS> stats(copied_replays_);
        for (uint32_t i = 0; i < copied_replays_; i++)
        {
            const HRESULT hr = c->GetData(queries_[i].Get(), &stats[i], sizeof stats[i], D3D11_ASYNC_GETDATA_DONOTFLUSH);
            if (hr == S_FALSE)
                return out;
            if (FAILED(hr))
            {
                out.state = SceneRead::State::failed;
                out.why = "the stream-output statistics could not be read (" + hresult("GetData", hr) + ")";
                return out;
            }
        }

        D3D11_MAPPED_SUBRESOURCE mapped;
        if (depth_size_.width != 0)
        {
            const HRESULT hr = c->Map(depth_staging_.Get(), 0, D3D11_MAP_READ, D3D11_MAP_FLAG_DO_NOT_WAIT, &mapped);
            if (hr == DXGI_ERROR_WAS_STILL_DRAWING)
                return out;
            if (FAILED(hr))
            {
                out.state = SceneRead::State::failed;
                out.why = "the depth copy could not be read (" + hresult("Map", hr) + ")";
                return out;
            }
            // 8 bytes a texel: the float depth, then the stencil and padding. The stencil is not taken from here: by the
            // present the game's later passes have written over it.
            out.depth.resize(size_t(depth_size_.width) * depth_size_.height);
            for (uint32_t y = 0; y < depth_size_.height; y++)
                for (uint32_t x = 0; x < depth_size_.width; x++)
                    std::memcpy(&out.depth[size_t(y) * depth_size_.width + x],
                        static_cast<const uint8_t *>(mapped.pData) + size_t(y) * mapped.RowPitch + x * 8, sizeof(float));
            c->Unmap(depth_staging_.Get(), 0);
            out.render = depth_size_;
        }
        if (gbuffer_back_)
        {
            std::vector<uint8_t> depth_stencil;
            for (const auto &[back, bytes] : { std::pair { &normals_back_, &out.normals }, std::pair { &mask_back_, &out.mask },
                     std::pair { &irradiance_back_, &out.irradiance }, std::pair { &stencil_back_, &depth_stencil }, std::pair { &albedo_back_, &out.albedo } })
            {
                if (!back->copied())
                    continue;
                const Readback::Read r = back->read(c, *bytes);
                if (r == Readback::Read::not_ready)
                    return SceneRead {};
                if (r == Readback::Read::failed)
                    bytes->clear();
            }
            // The combine step's depth copy, 8 bytes a texel like the one above: its stencil is the G-buffer's.
            out.stencil.resize(depth_stencil.size() / 8);
            for (size_t i = 0; i < out.stencil.size(); i++)
                out.stencil[i] = depth_stencil[i * 8 + 4];
        }
        if (hdr_back_copied_)
        {
            std::vector<uint8_t> bytes;
            const Readback::Read r = hdr_back_.read(c, bytes);
            if (r == Readback::Read::not_ready)
                return SceneRead {};
            out.hdr.resize(r == Readback::Read::ok ? bytes.size() / 4 : 0);
            std::memcpy(out.hdr.data(), bytes.data(), out.hdr.size() * 4);
        }
        if (picture_copied_)
        {
            out.picture = picture_.read(c, D3D11_MAP_FLAG_DO_NOT_WAIT);
            if (!out.picture)
                return SceneRead {};
        }
        // The alpha programs' constants and the atlas: their copies stay unread, and nothing waits, until the GPU is done.
        for (const auto &[buffer, bytes, words, atlas] : { std::tuple { constants_staging_.Get(), copied_constants_, &out.constants, false },
                 std::tuple { atlas_staging_.Get(), uint64_t(copied_tiles_) * kTileBytes, static_cast<std::vector<uint32_t> *>(nullptr), true } })
        {
            if (bytes == 0 || buffer == nullptr)
                continue;
            const HRESULT hr = c->Map(buffer, 0, D3D11_MAP_READ, D3D11_MAP_FLAG_DO_NOT_WAIT, &mapped);
            if (hr == DXGI_ERROR_WAS_STILL_DRAWING)
                return SceneRead {};
            if (FAILED(hr))
            {
                out = {};
                out.state = SceneRead::State::failed;
                out.why = std::string(atlas ? "the alpha atlas" : "the alpha constants") + " could not be read (" + hresult("Map", hr) + ")";
                return out;
            }
            const auto *data = static_cast<const uint8_t *>(mapped.pData);
            if (atlas)
                out.atlas.assign(data, data + bytes);
            else
                words->assign(reinterpret_cast<const uint32_t *>(data), reinterpret_cast<const uint32_t *>(data + bytes));
            c->Unmap(buffer, 0);
        }

        out.records = copied_;
        for (SceneDrawRecord &r : out.records)
        {
            out.full |= r.skip == DrawSkip::buffer_full;
            if (r.skip != DrawSkip::none)
                continue;
            // Every replay streams one corner a primitive: a point replay its points, a tessellated one the three points
            // stream_triangles_gs.hlsl emits for each triangle.
            const D3D11_QUERY_DATA_SO_STATISTICS &s = stats[r.query];
            r.corners = s.NumPrimitivesWritten;
            r.corners_needed = std::max(s.PrimitivesStorageNeeded, s.NumPrimitivesWritten);
        }
        out.wanted = copied_wanted_;
        const HRESULT hr = c->Map(so_staging_.Get(), 0, D3D11_MAP_READ, D3D11_MAP_FLAG_DO_NOT_WAIT, &mapped);
        if (hr == DXGI_ERROR_WAS_STILL_DRAWING)
            return SceneRead {};
        if (FAILED(hr))
        {
            out = {};
            out.state = SceneRead::State::failed;
            out.why = "the stream-output copy could not be read (" + hresult("Map", hr) + ")";
            return out;
        }
        StreamRead stream = unpack_stream(out.records, static_cast<const float *>(mapped.pData), buffer_bytes_ / kCornerBytes, hints_);
        c->Unmap(so_staging_.Get(), 0);
        out.clip = std::move(stream.clip);
        out.attributes = std::move(stream.attributes);
        out.overran = stream.overran;
        out.unwritten = stream.unwritten;
        if (!out.clip.empty())
            support_ = 1;
        out.state = SceneRead::State::ok;
        return out;
    }

    bool SceneGpu::grow(uint64_t wanted_corners)
    {
        const uint64_t wanted = std::min(kBufferMax, (wanted_corners * kCornerBytes * 5 / 4 + kBufferStep - 1) / kBufferStep * kBufferStep);
        if (wanted <= buffer_bytes_)
            return false;
        // make_buffers keeps the old buffers when the new ones fail.
        return make_buffers(wanted);
    }
}
